function BlobImg({b64, alt, style, onClick}){
  const [src,setSrc]=useState(null);
  useEffect(()=>{
    if(!b64){return;}
    // b64 is already a data URL
    setSrc(b64);
  },[b64]);
  if(!src)return <div style={{...style,background:"#e8e4dd",display:"flex",alignItems:"center",justifyContent:"center",color:"#aaa",fontSize:12}}>Loading…</div>;
  return <img src={src} alt={alt||""} style={style} onClick={onClick}/>;
}

function VideoPlayer(){
  const [src,setSrc]=useState(null);
  useEffect(()=>{
    const b=atob(VIDEO_B64),arr=new Uint8Array(b.length);
    for(let i=0;i<b.length;i++)arr[i]=b.charCodeAt(i);
    const url=URL.createObjectURL(new Blob([arr],{type:"video/mp4"}));
    setSrc(url);
    return()=>URL.revokeObjectURL(url);
  },[]);
  if(!src)return <div style={{height:240,background:"#e8e4dd",display:"flex",alignItems:"center",justifyContent:"center",color:"#888",fontSize:13,borderRadius:"12px 12px 0 0"}}>Loading video…</div>;
  return <video src={src} controls playsInline style={{width:"100%",height:240,objectFit:"cover",display:"block",borderRadius:"12px 12px 0 0",background:"#000"}}/>;
}

